SELECT 'batch_004_f5fb4151_wav_05' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0eb138eb-495','sm-upload-1fa15574-293','sm-upload-884d87d8-f8d','sm-upload-8d28b118-c2d','sm-upload-c2754cf8-e65') AND album_id='al-04d3a5af95307e73856b859df5fb4151') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-0eb138eb-495','sm-upload-1fa15574-293','sm-upload-884d87d8-f8d','sm-upload-8d28b118-c2d','sm-upload-c2754cf8-e65') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-04d3a5af95307e73856b859df5fb4151' AND name='世界沉睡童话') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-04d3a5af95307e73856b859df5fb4151') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-04d3a5af95307e73856b859df5fb4151') AS calculated_size;
